defmodule Astraea.External.TffPrinter do
  @moduledoc """
  Encodes `Astraea.Arena` clause sets as first-order TPTP TFF0 problems for
  first-order provers (applicative encoding with lambda lifting).

  The encoding, in the spirit of Leo-III's `leo.modules.encoding`:
    * every HOL type becomes a TFF sort (`$i`, user base types, `astraea_bool` for
      `$o` in term position, `astraea_fun_<type_id>` for function types)
    * every constant, Skolem symbol, and variable is nullary; application at function
      type `t` is the binary function `astraea_app_<t>`
    * Boolean terms are turned into formulas with `astraea_holds/1`
    * lambda abstractions and formulas in term position are lifted into fresh
      symbols over their free variables, defined by axioms `d<k>`

  The encoding is sound for refutations: each fresh symbol is defined conservatively
  and every Henkin model of the clauses induces a model of the encoding, so an
  unsatisfiable encoding implies an unsatisfiable clause set. It is incomplete
  (no extensionality or Boolean axioms), so `Satisfiable` answers carry no meaning.
  Clause `i` is named `c<i>`, as in `Astraea.External.ThfPrinter`.
  """

  alias Astraea.{Arena, ProofChecker}

  # Node tags (u8) matching `Astraea.Arena`
  @tag_const 1
  @tag_bvar 2
  @tag_fvar 3
  @tag_app 4
  @tag_lam 5
  @tag_eq 6
  @tag_not 7
  @tag_or 8
  @tag_forall 9
  @tag_skolem 10
  @tag_comb 11

  @lower_word ~r/^[a-z][A-Za-z0-9_]*$/

  @doc """
  Renders `clauses` as a TFF0 problem. Options:
    * `:role` - formula role for every clause (default `"axiom"`)
    * `:name_prefix` - prefix for clause formula names (default `"c"`)

  Raises `ArgumentError` on combinator nodes, which never occur in clausifier output.
  """
  @spec problem(Arena.t(), [ProofChecker.clause()], keyword()) :: String.t()
  def problem(%Arena{} = arena, clauses, opts \\ []) do
    role = Keyword.get(opts, :role, "axiom")
    prefix = Keyword.get(opts, :name_prefix, "c")
    acc = %{consts: MapSet.new(), apps: MapSet.new(), lifted: %{}, decls: [], defs: []}

    {formulas, acc} =
      clauses
      |> Enum.with_index()
      |> Enum.map_reduce(acc, fn {clause, idx}, acc ->
        {body, acc} = clause_formula(arena, clause, acc)
        {["tff(", prefix, Integer.to_string(idx), ", ", role, ", ", body, ").\n"], acc}
      end)

    IO.iodata_to_binary([
      "% Generated by Astraea.External.TffPrinter (applicative encoding)\n",
      sort_decls(arena),
      "tff(astraea_holds_decl, type, astraea_holds: astraea_bool > $o).\n",
      symbol_decls(arena, acc),
      Enum.reverse(acc.decls),
      acc.defs |> Enum.reverse() |> Enum.with_index() |> Enum.map(&definition/1),
      formulas
    ])
  end

  defp clause_formula(arena, clause, acc) do
    lits = Enum.sort(clause)
    vars = clause_vars(arena, lits)

    {lit_strs, acc} =
      Enum.map_reduce(lits, acc, fn {pol, atom}, acc ->
        {f, acc} = formula(arena, atom, [], acc)
        {if(pol == :neg, do: ["(~ ", f, ")"], else: f), acc}
      end)

    disj =
      case lit_strs do
        [] -> "$false"
        _ -> ["(", Enum.intersperse(lit_strs, " | "), ")"]
      end

    {quantify(arena, Enum.map(vars, fn {id, ty} -> {var_name(id), ty} end), disj), acc}
  end

  defp clause_vars(arena, lits) do
    lits
    |> Enum.reduce(MapSet.new(), fn {_pol, atom}, acc ->
      MapSet.union(acc, Arena.free_vars(arena, atom))
    end)
    |> Enum.sort()
  end

  # ---------------------------------------------------------------------------
  # Formula positions (type $o)
  # ---------------------------------------------------------------------------

  defp formula(arena, id, ctx, acc) do
    {tag, _flags, _ty, left, right} = Arena.get_node(arena, id)

    case tag do
      @tag_not ->
        {a, acc} = formula(arena, left, ctx, acc)
        {["(~ ", a, ")"], acc}

      @tag_or ->
        {l, acc} = formula(arena, left, ctx, acc)
        {r, acc} = formula(arena, right, ctx, acc)
        {["(", l, " | ", r, ")"], acc}

      @tag_eq ->
        if Arena.type_of(arena, left) == Arena.ty_o() do
          {l, acc} = formula(arena, left, ctx, acc)
          {r, acc} = formula(arena, right, ctx, acc)
          {["(", l, " <=> ", r, ")"], acc}
        else
          {l, acc} = term(arena, left, ctx, acc)
          {r, acc} = term(arena, right, ctx, acc)
          {["(", l, " = ", r, ")"], acc}
        end

      @tag_forall ->
        name = "B#{length(ctx)}"
        {b, acc} = formula(arena, right, [{name, left} | ctx], acc)
        {["(! [", name, ": ", sort(arena, left), "]: ", b, ")"], acc}

      @tag_const ->
        case Map.fetch!(arena.symbol_names, left) do
          "$true" -> {"$true", acc}
          "$false" -> {"$false", acc}
          _ -> holds(arena, id, ctx, acc)
        end

      _ ->
        holds(arena, id, ctx, acc)
    end
  end

  defp holds(arena, id, ctx, acc) do
    {t, acc} = term(arena, id, ctx, acc)
    {["astraea_holds(", t, ")"], acc}
  end

  # ---------------------------------------------------------------------------
  # Term positions
  # ---------------------------------------------------------------------------

  defp term(arena, id, ctx, acc) do
    {tag, _flags, ty, left, right} = Arena.get_node(arena, id)

    case tag do
      @tag_const ->
        case Map.fetch!(arena.symbol_names, left) do
          "$" <> _ ->
            lift(arena, id, ctx, acc)

          name ->
            {const_name(name), %{acc | consts: MapSet.put(acc.consts, {const_name(name), ty})}}
        end

      @tag_skolem ->
        name = skolem_name(left)
        {name, %{acc | consts: MapSet.put(acc.consts, {name, ty})}}

      @tag_fvar ->
        {var_name(left), acc}

      @tag_bvar ->
        {name, _ty} = Enum.at(ctx, left)
        {name, acc}

      @tag_app ->
        fun_ty = Arena.type_of(arena, left)
        {f, acc} = term(arena, left, ctx, acc)
        {a, acc} = term(arena, right, ctx, acc)

        {["astraea_app_", Integer.to_string(fun_ty), "(", f, ", ", a, ")"],
         %{acc | apps: MapSet.put(acc.apps, fun_ty)}}

      @tag_comb ->
        raise ArgumentError, "combinator nodes are not supported by the TFF encoding"

      _lam_or_formula ->
        lift(arena, id, ctx, acc)
    end
  end

  # Replaces a lambda or Boolean term by `astraea_lift_<k>(free vars)` and records its
  # defining axiom. Bound variables of enclosing binders become extra arguments.
  defp lift(arena, id, ctx, acc) do
    free = free_args(arena, id, ctx)
    key = {id, free}

    {name, acc} =
      case Map.fetch(acc.lifted, key) do
        {:ok, name} ->
          {name, acc}

        :error ->
          name = "astraea_lift_#{map_size(acc.lifted)}"
          acc = %{acc | lifted: Map.put(acc.lifted, key, name)}
          ty = Arena.type_of(arena, id)
          lhs = applied(name, free)
          {body, acc} = definition_body(arena, id, ty, lhs, ctx, acc)

          decl = ["tff(", name, "_decl, type, ", name, ": ", signature(arena, free, ty), ").\n"]

          {name,
           %{acc | decls: [decl | acc.decls], defs: [quantify(arena, free, body) | acc.defs]}}
      end

    {applied(name, free), acc}
  end

  defp definition_body(arena, id, ty, lhs, ctx, acc) do
    case Arena.get_node(arena, id) do
      {@tag_lam, _flags, _ty, dom, body} ->
        x = "B#{length(ctx)}"
        {:arrow, _dom, cod} = Map.fetch!(arena.type_table, ty)
        app = ["astraea_app_", Integer.to_string(ty), "(", lhs, ", ", x, ")"]
        acc = %{acc | apps: MapSet.put(acc.apps, ty)}
        inner_ctx = [{x, dom} | ctx]

        {eq, acc} =
          if cod == Arena.ty_o() do
            {f, acc} = formula(arena, body, inner_ctx, acc)
            {["(astraea_holds(", app, ") <=> ", f, ")"], acc}
          else
            {t, acc} = term(arena, body, inner_ctx, acc)
            {["(", app, " = ", t, ")"], acc}
          end

        {["(! [", x, ": ", sort(arena, dom), "]: ", eq, ")"], acc}

      _boolean_term ->
        {f, acc} = formula(arena, id, ctx, acc)
        {["(astraea_holds(", lhs, ") <=> ", f, ")"], acc}
    end
  end

  # Free clause variables and loose bound variables of `id`, as `{name, type_id}`.
  defp free_args(arena, id, ctx) do
    fvars =
      arena |> Arena.free_vars(id) |> Enum.sort() |> Enum.map(fn {v, ty} -> {var_name(v), ty} end)

    bvars =
      arena
      |> loose_bvars(id, 0, MapSet.new())
      |> Enum.sort()
      |> Enum.map(&Enum.at(ctx, &1))

    fvars ++ bvars
  end

  defp loose_bvars(arena, id, depth, acc) do
    {tag, _flags, _ty, left, right} = Arena.get_node(arena, id)

    case tag do
      @tag_bvar when left >= depth ->
        MapSet.put(acc, left - depth)

      @tag_not ->
        loose_bvars(arena, left, depth, acc)

      t when t in [@tag_lam, @tag_forall] ->
        loose_bvars(arena, right, depth + 1, acc)

      t when t in [@tag_app, @tag_eq, @tag_or] ->
        loose_bvars(arena, right, depth, loose_bvars(arena, left, depth, acc))

      _ ->
        acc
    end
  end

  # ---------------------------------------------------------------------------
  # Declarations
  # ---------------------------------------------------------------------------

  defp sort_decls(arena) do
    arena.type_table
    |> Enum.sort()
    |> Enum.flat_map(fn
      {_id, :i} ->
        []

      {id, _ty} ->
        ["tff(sort_", Integer.to_string(id), ", type, ", sort(arena, id), ": $tType).\n"]
    end)
  end

  defp symbol_decls(arena, acc) do
    consts =
      acc.consts
      |> Enum.sort()
      |> Enum.with_index()
      |> Enum.map(fn {{name, ty}, idx} ->
        ["tff(sym_", Integer.to_string(idx), ", type, ", name, ": ", sort(arena, ty), ").\n"]
      end)

    apps =
      acc.apps
      |> Enum.sort()
      |> Enum.map(fn fun_ty ->
        {:arrow, dom, cod} = Map.fetch!(arena.type_table, fun_ty)
        id = Integer.to_string(fun_ty)

        [
          "tff(app_",
          id,
          ", type, astraea_app_",
          id,
          ": (",
          sort(arena, fun_ty),
          " * ",
          sort(arena, dom),
          ") > ",
          sort(arena, cod),
          ").\n"
        ]
      end)

    [consts, apps]
  end

  defp definition({body, idx}), do: ["tff(d", Integer.to_string(idx), ", axiom, ", body, ").\n"]

  defp signature(arena, [], ty), do: sort(arena, ty)
  defp signature(arena, [{_name, arg_ty}], ty), do: [sort(arena, arg_ty), " > ", sort(arena, ty)]

  defp signature(arena, args, ty) do
    arg_sorts = Enum.map_intersperse(args, " * ", fn {_name, arg_ty} -> sort(arena, arg_ty) end)
    ["(", arg_sorts, ") > ", sort(arena, ty)]
  end

  defp quantify(_arena, [], body), do: body

  defp quantify(arena, vars, body) do
    binders = Enum.map_intersperse(vars, ", ", fn {name, ty} -> [name, ": ", sort(arena, ty)] end)
    ["( ! [", binders, "]: ", body, " )"]
  end

  defp applied(name, []), do: name
  defp applied(name, args), do: [name, "(", Enum.map_intersperse(args, ", ", &elem(&1, 0)), ")"]

  defp sort(arena, ty_id) do
    case Map.fetch!(arena.type_table, ty_id) do
      :i -> "$i"
      :o -> "astraea_bool"
      {:base, name} -> base_sort(name)
      {:arrow, _dom, _cod} -> "astraea_fun_" <> Integer.to_string(ty_id)
    end
  end

  defp base_sort(name) do
    if Regex.match?(@lower_word, name), do: name, else: quote_atom(name)
  end

  # User symbols never start with `astraea_`, so generated names cannot collide.
  defp const_name(name) do
    if Regex.match?(@lower_word, name) and not String.starts_with?(name, "astraea_"),
      do: name,
      else: quote_atom("u_" <> name)
  end

  defp var_name(id), do: "V" <> Integer.to_string(id)

  defp skolem_name(hash) do
    "sk_" <> String.downcase(String.pad_leading(Integer.to_string(hash, 16), 8, "0"))
  end

  defp quote_atom(name) do
    "'" <> (name |> String.replace("\\", "\\\\") |> String.replace("'", "\\'")) <> "'"
  end
end
